export function generateHreflangTags(baseUrl: string, slug: string, languages: Language[]) {
  return languages.map(lang => ({
    rel: 'alternate',
    hreflang: lang.code,
    href: `${baseUrl}${lang.isDefault ? '' : '/' + lang.code}/articles/${slug}`
  }));
}

/* Pure CSS Baseline Grid Snapping */
:root {
  --baseline: 1.5rem; /* 24px base leading */
}

h1 {
  font-size: 3rem;
  line-height: calc(var(--baseline) * 2);
  margin-bottom: var(--baseline);
}

p {
  font-size: 1rem;
  line-height: var(--baseline);
  margin-bottom: var(--baseline);
}

// Impure: Mutates external state & relies on hidden time dependency
let requestCount = 0;
function logImpure(article: Article) {
  requestCount++;
  article.views = (article.views || 0) + 1;
  console.log(`Visited at ${Date.now()}`);
}

// Pure: Deterministic, immutable, and trivially testable
function computeWordCount(article: Readonly<Article>): number {
  return article.body.reduce((total, block) => {
    if (block.type === 'p' || block.type === 'quote') {
      return total + block.text.trim().split(/\s+/).length;
    }
    return total;
  }, 0);
}
